import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('История молитв', () => {
  test('PH-01 Пустая история — сообщение (подмена ответа) #6a86f800 @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. До перехода: подмена ответа prayer_completions пустым списком (только GET; реальные данные не меняются).
    await page.route('**/rest/v1/prayer_completions**', (route) => {
      if (route.request().method() !== 'GET') return route.continue();
      return route.fulfill({ json: [] });
    });

    // 2. Открыть `/journey/history`.
    await page.goto('/journey/history');
    await expect(page.getByText('עדיין לא נרשמה כאן אף תפילה שהושלמה.')).toBeVisible({ timeout: 20_000 });
  });
});
